@@ -1,2 +1,12 @@
 import { normalize } from './normalize.mjs';
 export const tagLabel = value => normalize(value);
+
+/**
+ * Normalize a list of tags: trim + lowercase each entry via `normalize`,
+ * drop empty entries, remove duplicates, and sort alphabetically.
+ * The input array is never mutated.
+ */
+export const normalizeTags = values => {
+  const tags = values.map(value => normalize(value));
+  return [...new Set(tags.filter(tag => tag !== ''))].sort();
+};
